SELECT Имена_станций.NAME AS Name1, Станции2014.YEAR, Станции2014.NUST, Станции2014.E, Станции2014.B, Станции2014!DON/IIf(Натура99!DON>0,Натура99!DON,0.699) AS don, Станции2014!podm/IIf(Натура99!podm>0,Натура99!podm,0.274) AS podm, IIf([int]>0,[int],0)+IIf([vork]>0,[vork],0) AS pech, Доп_угли2014!vork/IIf(Натура99!vork>0,Натура99!vork,0.677) AS Vork, Доп_угли2014!int/IIf(Натура99!int>0,Натура99!int,0.532) AS [int], Станции2014!kuzn/IIf(Натура99!kuzn>0,Натура99!kuzn,0.752) AS kuzn, IIf([sver]>0,[sver],0)+IIf([chel]>0,[chel],0)+IIf([kizel]>0,[kizel],0) AS Ural, Доп_угли2014!sver/IIf(Натура99!sver>0,Натура99!sver,0.316) AS sver, Доп_угли2014!chel/IIf(Натура99!chel>0,Натура99!chel,0.422) AS chel, Доп_угли2014!kizel/IIf(Натура99!kizel>0,Натура99!kizel,0.624) AS kizel, Станции2014!bashk/IIf(Натура99!bashk>0,Натура99!bashk,0.29) AS bashk, Станции2014!ekib/IIf(Натура99!ekib>0,Натура99!ekib,0.551) AS ekib, Станции2014!karag/IIf(Натура99!karag>0,Натура99!karag,0.502) AS karag, IIf([nazar]>0,[nazar],0)+IIf([ibor]>0,[ibor],0)+IIf([berez]>0,[berez],0)+IIf([per]>0,[per],0) AS kan, Доп_угли2014!nazar/IIf(Натура99!nazar>0,Натура99!nazar,0.484) AS nazar, Доп_угли2014!ibor/IIf(Натура99!ibor>0,Натура99!ibor,0.587) AS ibor, Доп_угли2014!berez/IIf(Натура99!berez>0,Натура99!berez,0.519) AS berez, Доп_угли2014!per/IIf(Натура99!per>0,Натура99!per,0.557) AS per, IIf([jer]>0,[jer],0)+IIf([karab]>0,[karab],0) AS TUNG, Доп_угли2014!jer/IIf(Натура99!jer>0,Натура99!jer,0.7) AS jer, Доп_угли2014!karab/IIf(Натура99!karab>0,Натура99!karab,0.72) AS karab, Станции2014!hak/IIf(Натура99!hak>0,Натура99!hak,0.656) AS hak, Станции2014!tuv/IIf(Натура99!tuv>0,Натура99!tuv,0.781) AS tuv, IIf([azey]>0,[azey],0)+IIf([cher]>0,[cher],0)+IIf([mug]>0,[mug],0) AS irkut, Доп_угли2014!azey/IIf(Натура99!azey>0,Натура99!azey,0.576) AS azey, Доп_угли2014!mug/IIf(Натура99!mug>0,Натура99!mug,0.584) AS mug, Доп_угли2014!cher/IIf(Натура99!cher>0,Натура99!cher,0.613) AS cher, IIf([gusin]>0,[gusin],0)+IIf([tugn]>0,[tugn],0) AS bur, Доп_угли2014!gusin/IIf(Натура99!gusin>0,Натура99!gusin,0.558) AS gusin, Доп_угли2014!tugn/IIf(Натура99!tugn>0,Натура99!tugn,0.711) AS tugn, IIf([har]>0,[har],0)+IIf([urt]>0,[urt],0) AS Chit, Доп_угли2014!har/IIf(Натура99!har>0,Натура99!har,0.47) AS har, Доп_угли2014!urt/IIf(Натура99!urt>0,Натура99!urt,0.62) AS urt, IIf([neru]>0,[neru],0)+IIf([pyak]>0,[pyak],0) AS ner, Доп_угли2014!neru/IIf(Натура99!neru>0,Натура99!neru,0.83) AS neru, Доп_угли2014!pyak/IIf(Натура99!pyak>0,Натура99!pyak,0.83) AS pyak, Станции2014!prim/IIf(Натура99!prim>0,Натура99!prim,0.388) AS prim, IIf([rai]>0,[rai],0)+IIf([erk]>0,[erk],0) AS raich, Доп_угли2014!rai/IIf(Натура99!rai>0,Натура99!rai,0.4) AS rai, Доп_угли2014!erk/IIf(Натура99!erk>0,Натура99!erk,0.43) AS erk, Станции2014!urg/IIf(Натура99!urg>0,Натура99!urg,0.645) AS urg, Станции2014!luch/IIf(Натура99!luch>0,Натура99!luch,0.256) AS luch, Станции2014!mag/IIf(Натура99!mag>0,Натура99!mag,0.64) AS mag, Станции2014!sah/IIf(Натура99!sah>0,Натура99!sah,0.596) AS sah, Станции2014!kamch/IIf(Натура99!kamch>0,Натура99!kamch,0.62) AS KAMCH, Станции2014!ushum/IIf(Натура99!ushum>0,Натура99!ushum,0.325) AS ushum, Станции2014.NUMB1120, Имена_станций.ordnumb AS numb1, Станции2014.DEP, Станции2014.OES, Станции2014.ER, Имена_областей.NAME AS oblname, Станции2014.VED, Имена_станций.Ведомство AS вед, Станции2014.OBL, Имена_станций.D, Имена_станций.R, Имена_ОЭС.name AS oesname, Имена_станций.MAIN, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.форэм, Станции2014.GK
FROM ((((Станции2014 LEFT JOIN Натура99 ON (Станции2014.NUMB1120=Натура99.NUMB1120) AND (Станции2014.YEAR=Натура99.YEAR)) LEFT JOIN Доп_угли2014 ON (Станции2014.YEAR=Доп_угли2014.YEAR) AND (Станции2014.NUMB1120=Доп_угли2014.NUMB1120)) INNER JOIN Имена_станций ON Станции2014.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_областей ON Станции2014.OBL=Имена_областей.OBL) INNER JOIN Имена_ОЭС ON Станции2014.OES=Имена_ОЭС.oes
WHERE (((Станции2014.YEAR)=2014) AND ((Станции2014.UGOL)>0));
